WITH periods AS (SELECT kind,CASE WHEN kind=0 THEN date_trunc('week',statement_timestamp() AT TIME ZONE 'UTC') ELSE date_trunc('month',statement_timestamp() AT TIME ZONE 'UTC') END AS utc_start FROM generate_series(0,1) kind), shifted AS (SELECT kind, utc_start+CASE WHEN $1='expired' THEN CASE WHEN kind=0 THEN interval '-1 week' ELSE interval '-1 month' END WHEN $1='future' THEN CASE WHEN kind=0 THEN interval '1 week' ELSE interval '1 month' END ELSE interval '0' END AS utc_start FROM periods) INSERT INTO public.track_tournament(type,slug,id_level,start_at,end_at,finalized_at) SELECT kind,CASE WHEN $1='custom-slug' THEN 'custom' WHEN kind=0 THEN to_char(utc_start,'IYYY-"W"IW') ELSE to_char(utc_start,'YYYY-MM') END,kind+1, (utc_start AT TIME ZONE 'UTC')+CASE WHEN $1='correct' THEN interval '6 hours' WHEN $1='custom-start' THEN interval '-1 hour' ELSE interval '0' END, ((utc_start+CASE WHEN kind=0 THEN interval '1 week' ELSE interval '1 month' END) AT TIME ZONE 'UTC') +CASE WHEN $1='correct' THEN interval '6 hours' WHEN $1='custom-end' THEN interval '1 hour' ELSE interval '0' END, CASE WHEN $1='finalized' THEN statement_timestamp() END FROM shifted
